/// <summary>
/// The MobDocQuarantineOrder class is the document handler for the quarantine order creation in Mobile Wms.
/// </summary>
[
    TFMTableName(tableStr(InventQuarantineOrder)),
    TFMDocumentType(classStr(TFMPostAdhocRegistration), staticMethodStr(MobConstants,QuarantineOrders)),
    TFMDocumentType(classStr(TFMLookup), staticMethodStr(MobConstants,QuarantineOrders)),
    TFMDocumentType(classStr(TFMPostAdhocRegistration),staticMethodStr(MobConstants, CreateQuarantineOrders)),
    TFMDocumentType(classStr(TFMGetRegistrationConfiguration),staticMethodStr(MobConstants, CreateQuarantineOrders)),
    TFMMenu(staticMethodStr(MobConstants,QuarantineOrders),"@MobileWMS:MobileWMS170","@MobileWMS:MobileWMS170",resourceStr(MobQuarantineOrderIcon),true,true,['Warehouse', 'Miscellaneous']),
    TFMMenu(staticMethodStr(MobConstants,CreateQuarantineOrders),"@MobileWMS:createQuarantineOrder","@MobileWMS:createQuarantineOrder",resourceStr(MobQuarantineOrderIcon),false,true,['Warehouse', 'Miscellaneous', 'Inbound'])
]
class MobDocQuarantineOrder extends TFMDocumentHandler
{
    InventTable                 inventTable;
    InventDim                   inventDim;
    InventQuarantineOrder       qOrder;
    TFMRequestQuarantineElement QuarantineRequest;
    boolean						showInfo;


}

